mapper.update:
update t_diagnose_plan a

    a.end_time = #{endTime, jdbcType=TIMESTAMP},

where a.diagnose_plan_id = #{diagnosePlanId, jdbcType=VARCHAR}

mapper.select:
select
a.diagnose_plan_id,
a.plan_name,
a.plan_type,
a.user_id,
a.start_time
from t_diagnose_plan a
where 1 = 1
and a.diagnose_plan_id =
    #{diagnosePlanId, jdbcType=VARCHAR}

and a.plan_name = #{planName, jdbcType=VARCHAR}
and a.plan_type = #{planType, jdbcType=VARCHAR}
and a.user_id = #{userId, jdbcType=BIGINT}
and start_time = #{startTime, jdbcType=TIMESTAMP}
